from ta_emss.utilities.oam.ruffconfigurator import RuffConfigurator
from traceback import format_exc
from ta_emss.utilities.SCFC_parser_lib.interfaces.SCFC_parser_main import ScfcParserMain
import time
import re
import os
import copy
import yaml
import decimal
import ast
import six


class OM(object):
    REL_MINOR_str2float = {
        'SP': 0.2,
        'A': 0.5,
        'B': 0.7,
        'C': 0.8,
        'ASP': 0.7,
        'ASP1': 0.8,
    }

    TYP_default = 'FL'
    MOC_parents = ['MRBTS', 'LNBTS', 'NRBTS', 'FTM']

    def __init__(self, enb_name, logger=None, ute_emss=None):
        super(OM, self).__init__()
        self.enb_name = enb_name
        self.logger = logger
        self.ute_emss = ute_emss
        self.emss = None
        self.configurators = {}
        self.named_configurators = {}
        self.last_config_id = 0
        self.emss_instance_id = re.search(r"(\d+)", self.enb_name).group(1)
        self._dict = {}
        self._migration = {}
        self._current_migration_rel = None
        self.debug = 0
        try:
            self.debug = int(os.environ['DEBUG_OM'])
        except Exception:
            pass

        if self.ute_emss is None:
            self.create_emss()
            self.create_ute_emss()
        self.get_enb_id()
        self.read_migrations()

    def configure(self, cfg, name=None, skip_ro=True, skip_np=True, skip_dc=False, send=True, activate=False):
        assert self.check_pddb(), "PDDB is not loaded"
        config_plan = self.get_config_plan(cfg, skip_ro, skip_np)
        assert self.configure_by_default_configurator(config_plan, name, skip_dc=skip_dc, send=send, activate=activate), "Cannot configure (%s)" % name

    def deconfigure(self, name=None):
        if name:
            return self.deconfigure_by_name(name)
        else:
            return self.deconfigure_last()

    def deconfigure_by_name(self, name):
        if name in self.named_configurators:
            return self.named_configurators.pop(name).deconfigure()
        elif name in self.configurators:
            return self.configurators.pop(name).deconfigure()
        else:
            assert self.log_error("Configurator not present"), "No such config name: %s" % name

    def deconfigure_last(self):
        if self.last_config_id > 0:
            name = self.get_config_name()
            self.last_config_id -= 1
            self.deconfigure(name)
        return self.last_config_id

    def delete(self, config_plan):
        return None

    def get_parent_tree(self, moc):
        ret = []
        if self.emss is not None:
            ret = self.emss.run_command("disp_all_tree", moc)
        elif self.ute_emss is not None:
            ret = self.ute_emss.run_emssim_command("disp_all_tree", moc, get_full_data=True)
        else:
            assert self.log_error("Cannot check if {} exists.".format(moc)), "EMSsim not connected"
        objs = []
        for dic in ret:
            if 'attributes' in dic:
                for clas in dic['attributes'].keys():
                    objs.append(clas)
        return objs

    def deconfigure_all(self):
        while self.deconfigure_last() > 0:
            pass
        self.last_config_id = 0
        self.configurators = {}

    def get_emss(self):
        return self.emss

    def get_ute_emss(self):
        return self.ute_emss

    def get_enb_id(self):
        if self.exists('ENB_ID'):
            return self.get('ENB_ID')
        enb_id = self.get_bts_id()
        if enb_id is not None:
            self.set('ENB_ID', enb_id)
        return enb_id

    def get_bts_id(self):
        if self.exists('BTS_ID'):
            return self.get('BTS_ID')
        bts_id = self.get_lnbts_enbid()
        if not bts_id:
            bts_id = self.get_bts_bts_id()
        if bts_id:
            bts_id = int(bts_id)
            self.set('BTS_ID', bts_id)
            return bts_id
        self.log_error("Cannot get bts id.")
        return None

    def set(self, name, value):
        self._dict[name] = value

    def unset(self, name):
        if name in self._dict:
            return self._dict.pop(name)
        return None

    def get(self, name):
        if name in self._dict:
            return self._dict[name]
        self.log_error("Requested dict key does not exist [%s]." % name)
        return None

    def exists(self, name):
        return name in self._dict

    def log_debug(self, msg):
        if self.debug:
            self.log_print(msg)

    def log_warn(self, msg):
        _msg = "WARNING: %s" % msg
        self.log_print(_msg)

    def log_error(self, msg, exc=None):
        _msg = "ERROR: %s" % msg
        self.log_print(_msg)
        if exc:
            self.log_print(format_exc())

    def log_print(self, msg):
        _id = self.get('ENB_ID') if self.exists('ENB_ID') else "NA"
        _msg = ("OM%s[%s]: " % (self.emss_instance_id, _id)) + str(msg)
        if self.logger:
            self.logger.info(_msg)
        print(_msg)

    def create_emss(self):
        pass

    def create_ute_emss(self):
        try:
            from ta_emss import ute_emss

            ute_emss_env_host = os.environ.get("EMSS_HOST")
            if ute_emss_env_host:
                ute_emss_host = ute_emss_env_host
            else:
                ute_emss_host = self.emss.get_connection().get_member(member_name='-HOST')
            ute_emss_port = 4000 + int(self.get_enb_id())
            self.ute_emss = ute_emss(emssim_name="ute_emss{}".format(self.emss_instance_id),
                                     host=ute_emss_host,
                                     port=ute_emss_port)
        except Exception as err:
            self.log_error("Cannot create ute_emss device.", err)

    def rel2dec(self, rel_str):
        srch_inc = re.search(r"^\d?\D+(\d+)([A-Z0-9_\-]*)", rel_str)
        enb_rel = 0
        if srch_inc:
            # FL16A/FL16, SBTS20A, 5G19A, SBTS20B_1913_001_0.0, SBTS20-07-2001
            enb_rel = int(srch_inc.group(1))
            enb_rel_minor_any = srch_inc.group(2)
            srch_inc_minor_digits = re.search(r"^-(\d+)", enb_rel_minor_any)
            if srch_inc_minor_digits:
                # FL16-05/FL16-00/FL17-02/SBTS20-07-2001
                enb_rel_minor = srch_inc_minor_digits.group(1)
                srch_inc_subminor_digits = re.search(r"^-\d+-(\d+)-(\d+)", enb_rel_minor_any)
                if srch_inc_subminor_digits:
                    # SBTS20-07-2001-001
                    enb_rel_subminor = srch_inc_subminor_digits.group(1)
                    enb_rel_subminor_inc = srch_inc_subminor_digits.group(2)
                    minor_subminor = enb_rel_minor + "." + enb_rel_subminor + enb_rel_subminor_inc
                    enb_rel += float(minor_subminor) / 10.0
                else:
                    # FL16-05/FL16-00/FL17-02
                    enb_rel += int(srch_inc_minor_digits.group(1)) / 10.0
            elif enb_rel_minor_any in self.REL_MINOR_str2float:
                # A, B
                enb_rel += self.REL_MINOR_str2float[enb_rel_minor_any]
            else:
                subrel = self.rel2subrel(rel_str)
                enb_rel += self.subrel2float(subrel)
        return enb_rel

    def rel2typ(self, rel_str):
        typ = self.TYP_default
        try:
            srch = re.search(r"^(\d?[A-Z]+)", rel_str)
            if srch:
                typ = srch.group(1)
        except Exception:
            typ = self.TYP_default
        return typ

    def rel2subrel(self, rel_str):
        srch = re.search(r"^\d?[A-Z]+\d+([A-Z]+\d?)", rel_str)
        if srch:
            # 5G19A/FL17ASP1/SBTS20B
            return srch.group(1)
        return None

    def subrel2float(self, subrel):
        if subrel:
            if subrel in self.REL_MINOR_str2float:
                return self.REL_MINOR_str2float[subrel]
            else:
                srch = re.search(r"R(\d+)", subrel)
                if srch:
                    subint = float(srch.group(1))
                    return subint / 10
        return 0

    def pddb_ver2dec(self, rel_str):
        rel = 0.0
        srch = re.search(r"^([^_]+)_([^_]+)_([^_]+)", rel_str)
        if srch:
            rel_str = srch.group(1)
            mjr_str = '0.0' + srch.group(2) + srch.group(3)
            rel = self.rel2dec(rel_str)
            mjr = float(mjr_str)
            rel += mjr
        return rel

    def get_enb_rel(self):
        if self.exists('ENB_REL'):
            enb_rel = self.get('ENB_REL')
            if enb_rel:
                return self.rel2dec(enb_rel)
        enb_rel = 0
        bld = self.get_emss_build_id()
        srch = re.search(r"^([^_]+)", bld)
        if srch:
            rel_str = srch.group(1)
            self.set('ENB_REL', rel_str)
            enb_rel = self.rel2dec(rel_str)
            self.log_print("ENB_REL=%s [%s]." % (str(enb_rel), rel_str))
        if not enb_rel:
            self.log_warn("Unsupported eNB build_id: %s." % bld)
        return enb_rel

    def get_pddb_version(self):
        version = None
        try:
            ret = self.ute_emss.run_emssim_command("pddb_version", get_full_data=True)
            version = ret[0]['version']
        except Exception:
            self.log_warn("Cannot get pddb version from emssim")
        return version

    def get_enb_rel_typ(self):
        self.get_enb_rel()
        return self.rel2typ(self.get('ENB_REL'))

    def check_pddb(self):
        if self.ute_emss is not None:
            cmd_ret = self.ute_emss.run_emssim_command("env", get_full_data=True)
            try:
                pddb_ver = cmd_ret[0]['env']['BTS']['PDDB_VERSION']
                if pddb_ver == "Unknown":
                    return False
            except Exception:
                self.log_error("Cannot verify PDDB (ret=%s)." % str(cmd_ret))
        return True

    def get_emss_build_id(self):
        if self.emss is not None:
            cmd_env = self.emss.run_command('env')
            cmd_ret = cmd_env.returned_data()
            if isinstance(cmd_ret, list) and ('build_id' in cmd_ret[0]):
                return cmd_ret[0]['build_id']
            self.log_error("Cannot get build id from emss (ret=%s)." % str(cmd_ret))
        if self.ute_emss is not None:
            (bld, cmd_ret) = self._get_ute_emss_build_id_from_env()
            if bld:
                return bld
            self.ute_emss.run_emssim_command("sw_version")
            (bld, cmd_ret) = self._get_ute_emss_build_id_from_env()
            if bld:
                return bld
            self.log_error("Cannot get build id from ute_emss (ret=%s)." % str(cmd_ret))
        return None

    def _get_ute_emss_build_id_from_env(self):
        cmd_ret = self.ute_emss.run_emssim_command("env", get_full_data=True)
        try:
            return (cmd_ret[0]['env']['BTS']['BUILD_ID'], cmd_ret)
        except Exception:
            return (None, cmd_ret)

    def get_bts_bts_id(self):
        bts_id = None
        try:
            cmd_ret = self.ute_emss.run_emssim_command("bts_get", "-BTS_ID", get_full_data=True)
            for ret_entry in cmd_ret:
                if 'msg' in ret_entry and ret_entry['msg'] == "Attr value":
                    bts_id = ret_entry['value']
                    break
        except Exception:
            return None
        return bts_id

    def get_lnbts_enbid(self):
        if self.emss:
            cmd_disp_all = self.emss.run_command('disp_all', object='LNBTS')
            cmd_disp_all_result = self.emss.get_command_result(cmd_disp_all)
            for i, entry in enumerate(cmd_disp_all_result):
                for kv in entry:
                    srch_res = re.search(r"LNBTS-(\d+)", kv)
                    if srch_res:
                        return srch_res.group(1)
        if self.ute_emss:
            srch = re.search(r"(\d+)", self.ute_emss.get_LNBTS_object_name(silent=True))
            if srch:
                return srch.group(1)
        return None

    def get_config_plan(self, cfg, skip_ro=True, skip_np=True):
        config_plan = []
        assert cfg, "Empty config plan"
        if isinstance(cfg, list):
            if all(isinstance(i, six.string_types) for i in cfg):
                for i in cfg:
                    config_plan += self.process_config_plan(self.read_config_from_file(i), skip_ro, skip_np)
                return config_plan
            else:
                config_plan = cfg
        elif isinstance(cfg, dict):
            config_plan = [cfg]
        else:
            if re.search(r"^\{", cfg):
                config_plan = [ast.literal_eval(cfg)]
            elif re.search(r"^\[", cfg):
                config_plan = ast.literal_eval(cfg)
            else:
                config_plan = self.read_config_from_file(cfg)
        return self.process_config_plan(config_plan, skip_ro, skip_np)

    def process_config_plan(self, config_plan, skip_ro, skip_np):
        config = []
        for cfg_entry in config_plan:
            if cfg_entry is None:
                continue
            modify_moi_entry = self._resolve_parameters(cfg_entry)
            modify_moi_entry = self._add_default_id(modify_moi_entry)
            for migrated_moi_mid in self.migrate_moi(modify_moi_entry):
                for migrated_moi in self._expand_id(migrated_moi_mid):
                    if skip_ro and self._is_obj_exists(migrated_moi):
                        migrated_moi = self.skip_not_modifiable(migrated_moi)
                    if skip_np and migrated_moi:
                        migrated_moi = self.skip_not_present(migrated_moi)
                    if migrated_moi:
                        self.log_debug("Adding CFG entry=[%s]." % migrated_moi)
                        config.append(migrated_moi)
        return config

    def _expand_id(self, migrated_moi):
        ret = []
        if 'ID' in migrated_moi and isinstance(migrated_moi['ID'], list):
            for mid in sorted(migrated_moi['ID']):
                new_entry = {}
                for attr in migrated_moi:
                    new_entry[attr] = migrated_moi[attr]
                new_entry['ID'] = mid
                ret.append(new_entry)
        elif 'MOC' in migrated_moi and 'ID' in migrated_moi and "ALL" in migrated_moi['ID']:
            if migrated_moi['ID'] == "ALL":
                migrated_moi['ID'] = self._get_all_mois(migrated_moi['MOC'])
            elif migrated_moi['ID'] == "ALL_FDD":
                migrated_moi['ID'] = self._get_all_mois_group(migrated_moi['MOC'], group_type="FDD")
            elif migrated_moi['ID'] == "ALL_TDD":
                migrated_moi['ID'] = self._get_all_mois_group(migrated_moi['MOC'], group_type="TDD")
            else:
                migrated_moi['ID'] = self._expand_id_all(migrated_moi['MOC'], migrated_moi['ID'])
            ret = self._expand_id(migrated_moi)
        else:
            if 'ID' not in migrated_moi and 'MOC' in migrated_moi:
                migrated_moi['ID'] = self._get_all_mois(migrated_moi['MOC'])
                ret = self._expand_id(migrated_moi)
            else:
                ret = [migrated_moi]
        return ret

    def _expand_id_all(self, moc, mid):
        mid_array = []
        mids = mid.split("-")
        parents = self._get_parents(moc)
        assert len(mids) == len(parents), "Incorrect number of IDs for %s (ID=%s, parents=%s)" % (moc, mids, parents)
        for i, yaml_id in enumerate(mids):
            if 'ALL' in yaml_id:
                ids = []
                unique_ids = []

                if yaml_id == 'ALL_FDD':
                    ids = self._get_all_mois_group(parents[i], group_type="FDD")
                elif yaml_id == 'ALL_TDD':
                    ids = self._get_all_mois_group(parents[i], group_type="TDD")
                elif yaml_id == 'ALL':
                    ids = self._get_all_mois(parents[i])
                else:
                    assert False, "Wrong ID ALL: %s" % yaml_id

                if not ids:
                    return []

                unique_ids = self._get_unique_last_ids(ids)
                mid_array.append(unique_ids)
            else:
                mid_array.append(yaml_id)
        mid_array_ext = self._extend_array(mid_array)
        return mid_array_ext

    def _get_unique_last_ids(self, ids):
        all_id_set = set()
        for all_id in ids:
            last_id = self._take_last_id(all_id)
            all_id_set.add(last_id)
        return sorted(all_id_set)

    def _take_last_id(self, mid):
        srch = re.search(r"-(\d+)$", mid)
        if srch:
            return (srch.group(1))
        return mid

    def _get_parents(self, moc):
        cmd_parents = self.ute_emss.emssim.cmd_parents()
        cmd_parents.run_silently(moc)
        cmd_parents_out = cmd_parents.returned_data()
        return cmd_parents_out['user_parents']

    def _extend_array(self, arr):
        ret = []
        for arr_el in arr:
            new_tab = []
            if isinstance(arr_el, list):
                if len(ret) > 0:
                    for ret_el in ret:
                        for arr_subel in arr_el:
                            new_tab.append("%s-%s" % (ret_el, arr_subel))
                else:
                    for arr_subel in arr_el:
                        new_tab.append(arr_subel)
            else:
                if len(ret) > 0:
                    for ret_el in ret:
                        new_tab.append("%s-%s" % (ret_el, arr_el))
                else:
                    new_tab.append(arr_el)
            ret = new_tab
        return ret

    def _is_obj_exists(self, moi):
        object_name = None
        if 'DEL' in moi:
            return 0

        if 'ID' in moi and moi['ID']:
            object_name = moi['MOC'] + '-' + moi['ID']

        if not object_name or 'KEY' in moi:  # workaround for TAF
            return 1

        attributes = self.ute_emss._get_cmd_disp_all_attributes(object_name, silent=True)

        if object_name in attributes:
            if attributes[object_name] is not None:
                return 1
        return 0

    def _get_all_mois(self, moc):
        ret = []

        attributes = self.ute_emss._get_cmd_disp_all_attributes(moc, silent=True)

        for moc in attributes:
            srch = re.search(r"^[^-]+-([\d-]+)", moc)
            if srch:
                ret.append(srch.group(1))
        return ret

    def _get_all_mois_group(self, moc, group_type):
        ids = set()
        dat_ret = self.ute_emss.run_emssim_command("disp_all_tree", [moc, "-dn_only"], get_full_data=True, can_fail=True)
        if dat_ret:
            group_type_postfix = "_" + group_type + "-"
            for entry in dat_ret:
                if 'msg' in entry and entry['msg'] == "DN" and group_type_postfix in entry['dn']:
                    patt = r"\/" + moc + r"-([\d-]+)"
                    srch = re.search(patt, entry['dn'])
                    if srch:
                        ids.add(srch.group(1))
        return sorted(ids)

    def skip_not_modifiable(self, moi):
        assert 'MOC' in moi, "Missing MOC key"
        moc = moi['MOC']
        attr = None
        new_moi = {}
        ext_keys = {}
        removed = False
        self.log_debug("skip_ro: MOI=%s." % str(moi))
        for attr in moi:
            try:
                if attr[0].islower():
                    if self.filter_attr_ro(new_moi, moi, attr):
                        removed = True
                else:
                    ext_keys[attr] = moi[attr]
            except Exception as exc:
                self.log_error("Cannot verify modification of attribute %s-%s." % (str(moc), str(attr)), exc=exc)

        if new_moi or not removed:
            for ext_key in ext_keys:
                new_moi[ext_key] = ext_keys[ext_key]
        self.log_debug("skip_ro: OUT=%s." % str(new_moi))
        return new_moi

    def filter_attr_ro(self, new_moi, moi, attr):
        attributes_details = self.ute_emss._get_cmd_attr_attributes_details(moi['MOC'], silent=True)
        was_ro = False
        if isinstance(moi[attr], list):
            new_list = []
            for subelem in moi[attr]:
                if isinstance(subelem, dict):
                    new_dict = {}
                    for subattr in subelem:
                        if self.is_attr_ro("{}.{}".format(attr, subattr), attributes_details):
                            was_ro = True
                            continue
                        new_dict[subattr] = subelem[subattr]
                    if new_dict:
                        new_list.append(new_dict)
                else:
                    new_list.append(subelem)
            if new_list:
                new_moi[attr] = new_list
            self.log_debug("skip_ro: [%s-%s]: old_list=%s, new_list=%s." % (moi['MOC'], attr, str(moi[attr]), str(new_list)))
        else:
            if self.is_attr_ro(attr, attributes_details):
                was_ro = True
            else:
                new_moi[attr] = moi[attr]
        return was_ro

    def is_attr_ro(self, attr, attributes_details):
        for attr_det in attributes_details:
            if attr.lower() == attr_det.lower():
                if attributes_details[attr_det]['MOD'] == 'Y':
                    return False
                else:
                    return True
        return False

    def skip_not_present(self, moi):
        if 'MOC' not in moi:
            return moi
        moc = moi['MOC']
        attr = None
        new_moi = {}
        ext_keys = {}
        removed = False
        self.log_debug("skip_np: MOI=%s." % str(moi))
        for attr in moi:
            try:
                if attr[0].islower():
                    if self.filter_attr_np(new_moi, moi, attr):
                        removed = True
                else:
                    ext_keys[attr] = moi[attr]
            except Exception as exc:
                self.log_error("Cannot verify presence of attribute %s-%s." % (str(moc), str(attr)), exc=exc)

        if new_moi or not removed:
            for ext_key in ext_keys:
                new_moi[ext_key] = ext_keys[ext_key]
        self.log_debug("skip_np: OUT=%s." % str(new_moi))
        return new_moi

    def filter_attr_np(self, new_moi, moi, attr):
        attributes_details = self.ute_emss._get_cmd_attr_attributes_details(moi['MOC'], silent=True)
        for attr_det in attributes_details:
            if attr.lower() == attr_det.lower():
                new_moi[attr] = moi[attr]
                return False
        return True

    def configure_by_default_configurator(self, config_plan, name, skip_dc=False, send=True, activate=False):
        configurator = None
        use_named = False

        if skip_dc or not send:
            configurator = self.get_default_configurator(config_plan, name, send=send, activate=activate)
            return configurator.configure()

        if name is not None:
            use_named = True
        else:
            name = self.get_next_config_name()

        try:
            configurator = self.get_default_configurator(config_plan, name, send=send, activate=activate)
        except Exception as err:
            self.log_error("Cannot get configurator for plan=%s." % name, err)
        assert configurator is not None, """
            No configurator for plan=%s.
            Make sure you're not using indexless configuration without
            RUFF server running.""" % name

        if use_named:
            self.named_configurators[name] = configurator
        else:
            self.configurators[name] = configurator

        return configurator.configure()

    def get_default_configurator(self, config_plan, name, send=True, activate=False):
        return RuffConfigurator(self, config_plan, name, send=send, activate=activate)

    def convert_xml(self, cfg_file, out_path=None):
        if out_path is None:
            xml_file = os.path.basename(cfg_file)
            default_yaml_path = self._get_default_yaml_path()
            out_path = os.path.join(default_yaml_path, self._replace_xml_to_yaml(xml_file))
        else:
            out_path = self._handle_output_path(cfg_file, out_path)
        ScfcParserMain().convert(self.ute_emss.emss_host, self.ute_emss.emss_port, cfg_file, out_path)
        assert os.path.isfile(out_path), "SCFC_parser: Yaml does not exist after scfc convertion in " + out_path
        self.log_print("SCFC_parser: Yaml created in " + out_path)
        return out_path

    def convert_json(self, cfg_file):
        json_file = os.path.basename(cfg_file)
        default_yaml_path = self._get_default_yaml_path()
        out_path = os.path.join(default_yaml_path, self._replace_json_to_yaml(json_file))
        cfg_json = self.load_yaml(cfg_file)
        cfg_yaml = self._json2yaml(cfg_json)
        with open(out_path, "w") as yaml_handler:
            yaml_handler.write(yaml.safe_dump(cfg_yaml, encoding='utf-8', allow_unicode=True, default_flow_style=False).decode('utf-8', 'replace'))
        return out_path

    def _json2yaml(self, cfg_json):
        ret_yaml = []
        assert isinstance(cfg_json, list), "JSON list expected. Got=%s" % str(cfg_json)
        for moc_json_dict in cfg_json:
            yaml_dict = {}
            dist_name = moc_json_dict.get('distName')
            parameters = moc_json_dict.get('parameters') or []
            operation = moc_json_dict.get('operation')

            yaml_dict['DN'] = dist_name
            moc = self._dist_name_to_moc(dist_name)
            yaml_dict['ID'] = self._dist_name_to_id(dist_name)
            if operation == 'delete':
                yaml_dict['DEL'] = moc
            else:
                yaml_dict['MOC'] = moc

            for param in parameters:
                param_name = param['parameterName']
                param_value = param['value']
                yaml_dict[param_name] = param_value
            ret_yaml.append(yaml_dict)
        self.log_print("YAML FROM JSON=%s" % str(ret_yaml))
        return ret_yaml

    def _dist_name_to_moc(self, dist_name):
        mo_class = None
        try:
            moi_list = dist_name.split("/")
            mo_class = moi_list[-1].split("-")[0]
        except Exception:
            self.log_error("Cannot get MO class from dist_name: %s" % str(dist_name))
        return mo_class

    def _dist_name_to_id(self, dist_name):
        ret_id = None
        try:
            moi_list = dist_name.split("/")
            for moi in reversed(moi_list):
                [mo_class, mo_id] = moi.split("-")
                if mo_class in self.MOC_parents:
                    if ret_id is None:
                        ret_id = mo_id
                    break
                if ret_id is None:
                    ret_id = mo_id
                else:
                    ret_id = mo_id + '-' + ret_id
            assert ret_id is not None
        except Exception:
            self.log_error("Cannot get MO id from dist_name: %s" % str(dist_name))
            raise
        return ret_id

    def _handle_output_path(self, xml_file, out_path):
        if os.path.isdir(out_path):
            file = self._replace_xml_to_yaml(os.path.split(xml_file)[1])
            return os.path.join(out_path, file)
        assert not os.path.exists(out_path), "Output file " + out_path + " already exists!"
        return out_path

    def _is_xml(self, cfg_file):
        pattern = re.compile(r"\.xml$")
        return pattern.search(cfg_file)

    def _is_json(self, cfg_file):
        pattern = re.compile(r"\.json$")
        return pattern.search(cfg_file)

    def _replace_xml_to_yaml(self, xml_file):
        ts = time.strftime("_%d%m%y%H%M%S")
        return xml_file.replace(".xml", ts + ".yaml")

    def _replace_json_to_yaml(self, json_file):
        ts = time.strftime("_%d%m%y%H%M%S")
        return json_file.replace(".json", ts + ".yaml")

    def _get_default_yaml_path(self):
        path = "/tmp/YAMLS"
        if not os.path.exists(path):
            os.mkdir(path)
            assert os.path.exists(path), "Cannot create dir %s" % path
        return path

    def _handle_file(self, cfg_file):
        path = cfg_file
        if self._is_xml(cfg_file):
            path = self.convert_xml(cfg_file)
        elif self._is_json(cfg_file):
            path = self.convert_json(cfg_file)
        return path

    def read_config_from_file(self, cfg_file):
        config = []
        cfg_file = self._handle_file(cfg_file)
        cfg_file_path = self.get_config_path(cfg_file)
        self.log_print("Configuring: %s" % cfg_file_path)
        try:
            config = self.load_yaml(cfg_file_path)
        except IOError as err:
            self.log_error("Cannot read config from file=%s." % cfg_file_path)
            raise err
        except IndexError as err:
            self.log_error("Index error while reading config from file=%s." % cfg_file_path)
            raise err
        return config

    def load_yaml(self, cfg_file_path):
        yaml.Loader.add_constructor(u'tag:yaml.org,2002:bool', yaml_custom_constructor)
        fcfg = open(cfg_file_path, 'r')
        config = yaml.load(fcfg, Loader=yaml.Loader)
        fcfg.close()
        self.log_debug("YAML(%s)=%s." % (cfg_file_path, str(config)))
        return config

    def get_config_path(self, cfg_file):
        if os.path.isfile(cfg_file):
            return cfg_file

        if not cfg_file.startswith('/'):
            cfg_file = os.path.join(self.get_repo_dir(), cfg_file)

        if self.is_yaml_ext(cfg_file):
            assert os.path.isfile(cfg_file), "Missing yaml file %s" % cfg_file
            return cfg_file

        full_cfg_file_path = self.get_config_file_by_rel(cfg_file)
        assert full_cfg_file_path, "Cannot get path to yaml for path %s." % (cfg_file)
        return full_cfg_file_path

    def is_yaml_ext(self, cfg_file):
        if re.search(r"\.yaml$", cfg_file, flags=re.IGNORECASE):
            return True
        if re.search(r"\.yml$", cfg_file, flags=re.IGNORECASE):
            return True
        return False

    def get_repo_dir(self):
        homedir = os.environ.get("HOME")
        return homedir

    def get_sorted_files_from_path(self, path):
        return sorted(os.listdir(path))

    def create_file_name_using_pattern(self, cfg_file_basename, enb_typ):
        patt = r"^%s[-_](%s\d+[RASP1-9BC]*)\.yaml$" % (cfg_file_basename, enb_typ)
        return patt

    def get_max_rel_and_find_files_with_patt(self, files, files_dict, patt):
        max_rel = None
        for fname in files:
            srch = re.search(patt, fname)
            if srch:
                rel_dec = self.rel2dec(srch.group(1))
                if max_rel is None:
                    max_rel = rel_dec
                if max_rel < rel_dec:
                    max_rel = rel_dec
                files_dict[rel_dec] = fname
        return max_rel

    def get_current_or_max_rel_file(self, curr_rel, files_dict, max_rel):
        ret = None
        if curr_rel in files_dict:
            ret = files_dict[curr_rel]
        elif max_rel and curr_rel > max_rel:
            ret = files_dict[max_rel]
        return ret

    def get_prev_rel_file(self, curr_rel, files_dict):
        ret = None
        prev_rel_dec = None
        for rel_dec in sorted(files_dict, key=float):
            if prev_rel_dec and prev_rel_dec < curr_rel < rel_dec:
                ret = files_dict[prev_rel_dec]
            prev_rel_dec = rel_dec
        return ret

    def get_correct_rel(self, curr_rel, files_dict, max_rel):
        ret = self.get_current_or_max_rel_file(curr_rel, files_dict, max_rel)
        if not ret:
            ret = self.get_prev_rel_file(curr_rel, files_dict)
        return ret

    def get_yaml_file_from_dir(self, patt, files):
        curr_rel = self.get_enb_rel()
        files_dict = {}
        max_rel = self.get_max_rel_and_find_files_with_patt(files, files_dict, patt)
        self.log_debug("files_dict=%s." % str(files_dict))
        ret = self.get_correct_rel(curr_rel, files_dict, max_rel)
        return ret

    def get_config_file_by_rel(self, cfg_file):
        cfg_file_basename = os.path.basename(cfg_file)
        cfg_file_dirname = os.path.dirname(cfg_file)
        default_yaml = "%s.yaml" % cfg_file_basename
        default_yaml_path = None

        files = self.get_sorted_files_from_path(cfg_file_dirname)
        if default_yaml in files:
            self.log_debug("Default yaml exists: %s." % default_yaml)
            default_yaml_path = os.path.join(cfg_file_dirname, default_yaml)
        patt = self.create_file_name_using_pattern(cfg_file_basename, self.get_enb_rel_typ())
        ret = self.get_yaml_file_from_dir(patt, files)

        if not ret and self.get_enb_rel_typ() != self.TYP_default:
            self.log_debug("Couldn't find yaml for {}. Trying with default type({})".format(self.get_enb_rel_typ(), self.TYP_default))
            patt = self.create_file_name_using_pattern(cfg_file_basename, self.TYP_default)
            ret = self.get_yaml_file_from_dir(patt, files)

        if not ret:
            ret = default_yaml_path
        if cfg_file_dirname and ret:
            return os.path.join(cfg_file_dirname, ret)
        return None

    def _resolve_par(self, value):
        resolved = False
        orig_value = value
        while True:
            srch = re.search(r"\$\{([^}]+)\}", str(value))
            if srch:
                resolved = True
                par_name = srch.group(1)
                par_val = self.get(name=par_name)
                string = "${%s}" % par_name
                value = value.replace(string, str(par_val))
            else:
                break
        if resolved:
            self.log_print("RESOLVED({}={})".format(orig_value, value))
        return value

    def _resolve_parameters(self, cfg_entry):
        entry = {}
        cp_cfg_entry = copy.deepcopy(cfg_entry)
        try:
            for attr in sorted(cp_cfg_entry):
                try:
                    entry[attr] = self._resolve_parameters_attr(cp_cfg_entry, attr)
                except AttributeError as err:
                    self.log_print("Attribute error(%s) [%s]. ENTRY=[%s]." % (str(attr), err, str(cp_cfg_entry)))
                except TypeError as err:
                    self.log_print("Type error(%s) [%s]. ENTRY=[%s]." % (str(attr), err, str(cp_cfg_entry)))
                except Exception as err:
                    self.log_print("Yaml error(%s) [%s]. ENTRY=[%s]." % (str(attr), err, str(cp_cfg_entry)))
        except KeyError as err:
            self.log_error("Yaml format error.", err)
        return entry

    def _add_default_id(self, entry):
        if 'ID' not in entry:
            if 'MOC' in entry and '/' in entry['MOC']:
                # 'MRBTS-1/LNBTS-1/LNCEL-3' | 'MRBTS-1/LNBTS-1/LNCEL'
                dn_parts = entry['MOC'].split('/')  # ['MRBTS-1', 'LNBTS-1', 'LNCEL-3'] | ['MRBTS-1', 'LNBTS-1', 'LNCEL']
                moi_parts = dn_parts[-1].split('-')  # ['LNCEL', '3'] | ['LNCEL']
                moc = moi_parts[0]  # 'LNCEL' | 'LNCEL'
                entry['MOC'] = '/'.join(dn_parts[:-1]) + '/' + moc  # 'MRBTS-1/LNBTS-1/LNCEL-3/LNCEL'
                entry_id = '-'.join(moi_parts[1:])  # '3'
                if entry_id:
                    entry['ID'] = entry_id
                else:
                    entry['ID'] = 'ALL'
            else:
                entry['ID'] = 'ALL'
        return entry

    def _resolve_parameters_attr(self, entry, attr):
        if isinstance(entry[attr], list):
            return self._resolve_parameters_attr_list(entry[attr])
        elif isinstance(entry[attr], dict):
            return self._resolve_parameters_attr_dict(entry[attr])
        return self._resolve_parameters_attr_var(entry[attr])

    def _resolve_parameters_attr_list(self, entry_list):
        ret_attr = []
        for i, attr_el in enumerate(entry_list):
            if isinstance(attr_el, dict):
                ret_attr.append(self._resolve_parameters_attr_dict(attr_el))
            else:
                ret_attr.append(self._resolve_parameters_attr_var(attr_el))
        return ret_attr

    def _resolve_parameters_attr_dict(self, entry_dict):
        ret_attr = {}
        for dct_key in entry_dict:
            ret_attr[dct_key] = self._resolve_parameters_attr_var(entry_dict[dct_key])
        return ret_attr

    def _resolve_parameters_attr_var(self, entry_var):
        if entry_var is None:
            return ""
        return self._resolve_par(str(entry_var))

    def migrate_moi(self, modify_moi_entry_arg):
        config = [modify_moi_entry_arg]
        for self._current_migration_rel in sorted(self._migration.keys(), key=decimal.Decimal):
            migrated_config = []
            for modify_moi_entry in config:
                if self.is_for_migration(modify_moi_entry):
                    for migrated_modify_moi in self.migrate_entry(modify_moi_entry):
                        migrated_config.append(migrated_modify_moi)
                else:
                    migrated_config.append(modify_moi_entry)
            config = migrated_config
        return config

    def migrate_entry(self, modify_moi_entry):
        ret_entries = []
        migrated_attrs = []
        for attr in sorted(modify_moi_entry):
            if attr == 'ID' or attr == 'MOC':
                continue
            if isinstance(modify_moi_entry[attr], list):
                migrated_subattrs = self.migrate_struct_attr(modify_moi_entry, attr)
                if migrated_subattrs:
                    for migrated_subattr_entry in migrated_subattrs:
                        ret_entries.append(migrated_subattr_entry)
            if attr not in modify_moi_entry:
                self.log_debug("ATTR removed: %s" % attr)
                continue
            new_modify_moi_entry = self.migrate_attr(modify_moi_entry, attr)
            if new_modify_moi_entry:
                migrated_attrs.append(attr)
                if 'DEL' not in new_modify_moi_entry:
                    ret_entries.append(new_modify_moi_entry)
        self.log_debug("Migrated ATTRs=%s." % migrated_attrs)
        if migrated_attrs:
            for attr in migrated_attrs:
                modify_moi_entry.pop(attr)
            if self.attr_exists(modify_moi_entry):
                ret_entries.append(modify_moi_entry)
        else:
            ret_entries.append(modify_moi_entry)
        return ret_entries

    def is_for_migration(self, modify_moi_entry):
        return (('MOC' in modify_moi_entry)
                and (self._current_migration_rel in self._migration)
                and (modify_moi_entry['MOC'] in self._migration[self._current_migration_rel]))

    def get_migr_attr_ci(self, moc, attr):
        for migr_attr in self._migration[self._current_migration_rel][moc]:
            if attr.lower() == migr_attr.lower():
                return migr_attr
        return None

    def get_migr_subattr_ci(self, moc, attr, subattr):
        attr_subattr = "%s.%s" % (attr, subattr)
        for migr_attr in self._migration[self._current_migration_rel][moc]:
            if attr_subattr.lower() == migr_attr.lower():
                return migr_attr
        return None

    def attr_exists(self, modify_moi_entry):
        for key in modify_moi_entry:
            if not key.isupper():
                return True
        return False

    def migrate_struct_attr(self, modify_moi_entry, attr):
        new_entries = {}
        migrated_subattrs = {}
        ret_entries = []

        self.migrate_struct_attr_dict(modify_moi_entry, attr, migrated_subattrs, new_entries)

        if migrated_subattrs:
            for i, subentry in enumerate(modify_moi_entry[attr]):
                if isinstance(subentry, dict):
                    for migrated_subattr in migrated_subattrs:
                        if migrated_subattr in subentry:
                            subentry.pop(migrated_subattr)
            is_empty = True
            for i, subentry in enumerate(modify_moi_entry[attr]):
                if subentry:
                    is_empty = False
            if is_empty:
                modify_moi_entry.pop(attr)

        if new_entries:
            ret_entries.append(modify_moi_entry)
            for new_moc in new_entries:
                for new_id in new_entries[new_moc]:
                    new_entry = {
                        'MOC': new_moc,
                        'ID': new_id
                    }
                    for new_attr in new_entries[new_moc][new_id]:
                        new_entry[new_attr] = new_entries[new_moc][new_id][new_attr]
                    ret_entries.append(new_entry)
        return ret_entries

    def migrate_struct_attr_dict(self, modify_moi_entry, attr, migrated_subattrs, new_entries):
        moc = modify_moi_entry['MOC']
        moc_id = modify_moi_entry['ID']
        for i, subentry in enumerate(modify_moi_entry[attr]):
            new_subattr_names = {}
            new_subattr_values = {}
            if isinstance(subentry, dict):
                for subattr in sorted(subentry):
                    new_subattr_moc = self.migrate_struct_subattr_moc(moc, attr, subattr)
                    new_subattr_id = self.migrate_struct_subattr_id(moc, attr, subattr, moc_id, i)
                    subattr_name = subattr
                    new_subattr_name = self.migrate_struct_subattr_name(moc, attr, subattr)
                    if new_subattr_name is not None:
                        new_subattr_names[subattr] = new_subattr_name
                        subattr_name = new_subattr_name
                    new_subattr_value = self.migrate_struct_subattr_value(moc, attr, subattr, subentry)
                    if new_subattr_value is not None:
                        new_subattr_values[subattr_name] = new_subattr_value
                    if new_subattr_moc and new_subattr_id and new_subattr_name:
                        if new_subattr_moc not in new_entries:
                            new_entries[new_subattr_moc] = {}
                        if new_subattr_id not in new_entries[new_subattr_moc]:
                            new_entries[new_subattr_moc][new_subattr_id] = {}
                        new_value = new_subattr_value if new_subattr_value else subentry[subattr]
                        new_entries[new_subattr_moc][new_subattr_id][new_subattr_name] = new_value
                        migrated_subattrs[subattr] = 1

            for (old_subattr_name, new_subattr_name) in new_subattr_names.items():
                subattr_entry = subentry[old_subattr_name]
                del subentry[old_subattr_name]
                if new_subattr_name == 'DEL':
                    self.log_debug("Deleted subattr in %s:%s[%d]: %s" % (moc, attr, i, old_subattr_name))
                    continue
                subentry[new_subattr_name] = subattr_entry
                self.log_debug("Renamed subattr in %s:%s[%d]: %s -> %s" % (moc, attr, i, old_subattr_name, new_subattr_name))
            for (new_subattr_name, new_subattr_value) in new_subattr_values.items():
                subentry[new_subattr_name] = new_subattr_value
                self.log_debug("Changed subattr value in %s:%s[%d]: %s -> %s" % (moc, attr, i, new_subattr_name, new_subattr_value))

    def migrate_struct_subattr_moc(self, moc, attr, subattr):
        attr_subattr_ci = self.get_migr_subattr_ci(moc, attr, subattr)
        if attr_subattr_ci is None:
            return None
        migration_subattr_entry = self.get_migration_attr_entry(moc, attr_subattr_ci)
        if 'MOC' in migration_subattr_entry:
            return migration_subattr_entry['MOC']
        return None

    def migrate_struct_subattr_id(self, moc, attr, subattr, moc_id, i):
        attr_subattr_ci = self.get_migr_subattr_ci(moc, attr, subattr)
        if attr_subattr_ci is None:
            return None
        migration_subattr_entry = self.get_migration_attr_entry(moc, attr_subattr_ci)
        if 'ID' in migration_subattr_entry:
            new_id = str(migration_subattr_entry['ID'])
            new_id = new_id.replace("${INDEX}", str(i))
            new_id = new_id.replace("${ID}", moc_id)
            return new_id
        return None

    def migrate_struct_subattr_name(self, moc, attr, subattr):
        attr_subattr_ci = self.get_migr_subattr_ci(moc, attr, subattr)
        if attr_subattr_ci is None:
            return None
        migration_subattr_entry = self.get_migration_attr_entry(moc, attr_subattr_ci)
        if 'NAME' in migration_subattr_entry:
            return migration_subattr_entry['NAME']
        if 'DEL' in migration_subattr_entry:
            return 'DEL'
        return None

    def migrate_struct_subattr_value(self, moc, attr, subattr, subentry):
        attr_subattr_ci = self.get_migr_subattr_ci(moc, attr, subattr)
        if attr_subattr_ci is None:
            return None
        migration_subattr_entry = self.get_migration_attr_entry(moc, attr_subattr_ci)
        if 'VALUE' in migration_subattr_entry:
            new_value = migration_subattr_entry['VALUE']
            if isinstance(new_value, dict):
                if 'TO_LIST' in new_value:
                    return self.migrate_struct_subattr_value_to_list(subentry[subattr], new_value['TO_LIST'])
            else:
                srch = re.search(r"^BITMASK\((\S+),(\S+)\)$", new_value)
                if srch:
                    val1 = self.process_migration_value(srch.group(1), subattr, subentry)
                    val2 = self.process_migration_value(srch.group(2), subattr, subentry)
                    return self.process_migration_value_bitmask(val1, val2)
            return migration_subattr_entry['VALUE']
        return None

    def migrate_struct_subattr_value_to_list(self, old_value, list_value):
        dct = {}
        for subname in list_value:
            new_val = str(list_value[subname])
            new_val = new_val.replace('${VALUE}', old_value)
            dct[subname] = new_val
        return [dct]

    def get_from_current_config(self, from_attr, subattr, subentry):
        self.log_debug("Getting from current config: from_attr=%s, subattr=%s, subentry=%s" % (from_attr, subattr, subentry))
        try:
            return subentry[from_attr]
        except Exception:
            self.log_warn("No subentry attribute: %s (%s)" % (from_attr, subentry))
        return None

    def process_migration_value_bitmask(self, val1, val2):
        ret = 0
        try:
            for v in range(int(val1), int(val2) + 1):
                ret += 2 ** v
        except Exception as exc:
            ret = None
            self.log_warn("Cannot process migration value bitmask: val1=%s, val2=%s (%s)" % (val1, val2, exc))
        return ret

    def process_migration_value(self, value, subattr, subentry):
        srch = re.search(r"^CFG\((\S+)\)$", value)
        if srch:
            return self.get_from_current_config(srch.group(1), subattr, subentry)
        return value

    def migrate_attr(self, modify_moi_entry, attr):
        moc = modify_moi_entry['MOC']
        attr_ci = self.get_migr_attr_ci(moc, attr)
        migration_moc_entry = self.get_migration_moc_entry(moc)

        migration_attr_entry = {}
        if attr_ci:
            migration_attr_entry = self.get_migration_attr_entry(moc, attr_ci)

            if 'ID' not in migration_attr_entry and 'ID' in migration_moc_entry:
                migration_attr_entry['ID'] = migration_moc_entry['ID']

            if 'MOC' not in migration_attr_entry and 'MOC' in migration_moc_entry:
                migration_attr_entry['MOC'] = migration_moc_entry['MOC']
        else:
            if 'ID' in migration_moc_entry:
                migration_attr_entry['ID'] = migration_moc_entry['ID']

            if 'MOC' in migration_moc_entry:
                migration_attr_entry['MOC'] = migration_moc_entry['MOC']

        if not migration_attr_entry:
            return None

        self.log_debug("Migrating MOC=%s, ATTR=%s..." % (moc, attr))

        new_entry = {}
        if 'DEL' in migration_attr_entry:
            new_entry['DEL'] = migration_attr_entry['DEL']
            return new_entry
        new_entry['MOC'] = self.migrate_attr_moc(migration_attr_entry, modify_moi_entry)
        if 'ID' in modify_moi_entry:
            new_entry['ID'] = self.migrate_attr_id(migration_attr_entry, modify_moi_entry)
            if new_entry['ID'] == 'ALL':
                new_entry['ID'] = self._get_all_mois(new_entry['MOC'])
        new_attr = self.migrate_attr_name(attr, migration_attr_entry, modify_moi_entry)
        if isinstance(new_attr, list):
            for nattr in new_attr:
                new_entry[nattr] = self.migrate_attr_value(attr, migration_attr_entry, modify_moi_entry)
        else:
            new_entry[new_attr] = self.migrate_attr_value(attr, migration_attr_entry, modify_moi_entry)
        return new_entry

    def get_migration_moc_entry(self, moc):
        migration_moc_entry = self._migration[self._current_migration_rel][moc]
        return migration_moc_entry

    def get_migration_attr_entry(self, moc, attr):
        migration_attr_entry = self._migration[self._current_migration_rel][moc][attr]
        return migration_attr_entry

    def migrate_attr_moc(self, migration_attr_entry, modify_moi_entry):
        if 'MOC' in migration_attr_entry:
            return migration_attr_entry['MOC']
        return modify_moi_entry['MOC']

    def migrate_attr_id(self, migration_attr_entry, modify_moi_entry):
        mod_moi_id = str(modify_moi_entry['ID'])
        if 'ID' in migration_attr_entry:
            migration_attr_entry_id = str(migration_attr_entry['ID'])

            if 'FILTER_ID' in migration_attr_entry:
                mod_moi_id = self.filter_attr_id(mod_moi_id, migration_attr_entry['FILTER_ID'])

            migration_attr_entry_id = migration_attr_entry_id.replace("${ID}", mod_moi_id)
            migration_attr_entry_id = self._resolve_par(migration_attr_entry_id)

            srch = re.search(r"FROM_ATTR\(([^:]+):([^,)]+),?(.*)\)", migration_attr_entry_id)
            if srch:
                from_moi = srch.group(1)
                from_attr = srch.group(2)
                default = srch.group(3)
                migration_attr_entry_id = self.get_attr_value(from_moi, from_attr, default)

            return migration_attr_entry_id
        return mod_moi_id

    def filter_attr_id(self, mod_moi_id, filter_id):
        srch = re.search(filter_id, mod_moi_id)
        if srch:
            return srch.group(0)
        return mod_moi_id

    def get_attr_value(self, moc, attr, default=None):
        val = default
        if self.ute_emss is not None:
            ret = self.ute_emss.run_emssim_command("disp", [moc, attr], get_full_data=True, can_fail=True)
            if ret:
                for entry in ret:
                    try:
                        val = entry['attributes'][moc][attr]
                        break
                    except Exception:
                        pass
        elif self.emss:
            cmd_disp = self.emss.run_command('disp', obj=moc, atr=attr)
            cmd_disp_result = self.emss.get_command_result(cmd_disp)
            if cmd_disp_result:
                for entry in cmd_disp_result:
                    try:
                        val = entry[moc][attr]['-VAL']
                        break
                    except Exception:
                        pass
        return val

    def migrate_attr_name(self, attr, migration_attr_entry, modify_moi_entry):
        if 'NAME' in migration_attr_entry:
            return migration_attr_entry['NAME']
        return attr

    def migrate_attr_value(self, attr, migration_attr_entry, modify_moi_entry):
        cfg_val = modify_moi_entry[attr]
        new_val = cfg_val
        try:
            new_val = migration_attr_entry['VALUE'][cfg_val]
        except Exception:
            pass
        try:
            if isinstance(cfg_val, list):
                new_val = self.migrate_attr_value_list(attr, modify_moi_entry, migration_attr_entry)
        except Exception:
            pass
        return new_val

    def migrate_attr_value_list(self, attr, modify_moi_entry, migration_attr_entry):
        new_list = []
        for list_elem in modify_moi_entry[attr]:
            if isinstance(list_elem, dict):
                new_dict = {}
                for subattr in list_elem:
                    new_dict[subattr] = list_elem[subattr]
                    for subattr_migr in migration_attr_entry:
                        if subattr.lower() == subattr_migr.lower():
                            new_dict[subattr] = self.migrate_attr_value(subattr, migration_attr_entry[subattr_migr], list_elem)
                new_list.append(new_dict)
            else:
                new_list.append(list_elem)
        return new_list

    def get_next_config_name(self):
        self.last_config_id += 1
        return self.get_config_name()

    def get_config_name(self):
        return "_CFG_{}_{:03d}".format(self.get('ENB_ID'), self.last_config_id)

    def read_migrations(self):
        migration_path = os.path.dirname(os.path.abspath(__file__)) + "/migration"
        if not os.path.isdir(migration_path):
            self.log_warn("Migration path does not exist (%s)." % migration_path)
        self.process_migrations(migration_path)

    def process_migrations(self, migration_path):
        pddb_version = self.get_pddb_version()

        self.log_print("PDDB VERSION=%s" % pddb_version)

        bts_rel_typ = self.rel2typ(pddb_version) if pddb_version else self.get_enb_rel_typ()
        enb_rel = self.pddb_ver2dec(pddb_version) if pddb_version else self.get_enb_rel()

        self.log_print("BTS RELEASE=%s" % enb_rel)
        self.log_print("BTS RELEASE TYPE=%s" % bts_rel_typ)

        filenames = self.get_sorted_files_from_path(migration_path)
        filenames = self.filter_migrations_by_typ(filenames, bts_rel_typ)

        for mfile in filenames:
            mrel = self.get_migr_file_rel(mfile)
            self.log_print("MIGR REL=%s" % mrel)
            if mrel is None:
                self.log_print("Skipping non-migration file=[%s]." % str(mfile))
                continue
            if enb_rel < mrel:
                self.log_print("Skipping migration for rel=[%s]." % str(mrel))
                continue
            self.log_print("Reading migration=[%s]." % str(mfile))
            try:
                yaml.Loader.add_constructor(u'tag:yaml.org,2002:bool', yaml_custom_constructor)
                mfd = open(migration_path + '/' + mfile)
                migr = yaml.load(mfd, Loader=yaml.Loader)
                self.add_migration(migr, mrel)
                mfd.close()
            except Exception as exc:
                self.log_error("Cannot read migration [%s]." % mfile, exc)

    def filter_migrations_by_typ(self, filenames, enb_rel_typ):
        migr_files = {}  # {'FL': [fl_file_list], 'SBTS': [sbts_file_list]}
        for mfile in filenames:
            if mfile.startswith('.'):
                continue
            mtyp = self.get_migr_file_typ(mfile)
            if mtyp is None:
                continue
            if mtyp not in migr_files:
                migr_files[mtyp] = []
            migr_files[mtyp].append(mfile)

        if enb_rel_typ in migr_files:
            return migr_files[enb_rel_typ]
        if self.TYP_default in migr_files:
            return migr_files[self.TYP_default]
        return []

    def get_migr_file_rel(self, mfile):
        srch = re.search(r"^(.*)\.", mfile)
        mrel = None
        if srch:
            mrel_str = srch.group(1)
            mrel = self.rel2dec(mrel_str)
        return mrel

    def get_migr_file_typ(self, mfile):
        srch = re.search(r"^(.*)\.", mfile)
        mtyp = None
        if srch:
            mrel_str = srch.group(1)
            mtyp = self.rel2typ(mrel_str)
        return mtyp

    def add_migration(self, migr, mrel):
        if mrel not in self._migration:
            self._migration[mrel] = {}
        for moc in migr:
            if moc not in self._migration[mrel]:
                self._migration[mrel][moc] = {}
            for attr in migr[moc]:
                if isinstance(migr[moc][attr], dict):
                    if attr not in self._migration[mrel][moc]:
                        self._migration[mrel][moc][attr] = {}
                    for akey in migr[moc][attr]:
                        self._migration[mrel][moc][attr][akey] = migr[moc][attr][akey]
                else:
                    self._migration[mrel][moc][attr] = migr[moc][attr]
        self.log_debug("MIGRATION(%s)=[%s]." % (mrel, self._migration[mrel]))

    def terminate_emss(self):
        if self.ute_emss:
            self.log_print("Terminating ute_emss...")
            self.ute_emss.terminate_emss_instance()
            self.ute_emss = None

    def get_last_configurator(self, name=None):
        if name:
            return self.named_configurators[name]
        return self.configurators[self.get_config_name()]


def yaml_custom_constructor(loader, node):
    value = loader.construct_scalar(node)
    return value
